import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'.pdf', '.docx', '.xlsx', '.csv'}

def sanitize_filename(filename):
    """Remove directory traversal but preserve the filename structure."""
    # Strip path separators to prevent directory traversal
    cleaned = filename.replace('/', '').replace('\\', '')
    # Collapse multiple dots (but keep extension)
    while '..' in cleaned:
        cleaned = cleaned.replace('..', '.')
    return cleaned

def get_file_metadata(filepath):
    """Extract metadata from uploaded file using exiftool."""
    try:
        result = subprocess.run(
            ['exiftool', '-json', filepath],
            capture_output=True,
            text=True,
            timeout=10
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        return '{"error": "timeout"}'

def convert_document(filepath, output_format):
    """Convert document to requested format using LibreOffice."""
    output_dir = tempfile.mkdtemp(prefix='convert_')
    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {output_dir} {filepath}'
    proc = subprocess.Popen(
        cmd,
        shell=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE
    )
    stdout, stderr = proc.communicate(timeout=30)
    if proc.returncode != 0:
        return None, stderr.decode()
    # Find the output file
    for f in os.listdir(output_dir):
        return os.path.join(output_dir, f), None
    return None, 'No output generated'

@app.route('/api/documents/upload', methods=['POST'])
def upload_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if not file.filename:
        return jsonify({'error': 'Empty filename'}), 400

    filename = sanitize_filename(file.filename)
    ext = os.path.splitext(filename)[1].lower()

    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': f'Extension {ext} not allowed'}), 400

    filepath = os.path.join(UPLOAD_DIR, filename)
    file.save(filepath)

    # Extract metadata
    metadata = get_file_metadata(filepath)

    return jsonify({
        'filename': filename,
        'path': filepath,
        'metadata': metadata
    }), 201

@app.route('/api/documents/convert', methods=['POST'])
def convert():
    data = request.get_json()
    if not data or 'filename' not in data or 'format' not in data:
        return jsonify({'error': 'filename and format required'}), 400

    filename = sanitize_filename(data['filename'])
    output_format = data['format']

    # Validate output format
    allowed_formats = ['pdf', 'docx', 'html', 'txt']
    if output_format not in allowed_formats:
        return jsonify({'error': 'Invalid output format'}), 400

    filepath = os.path.join(UPLOAD_DIR, filename)
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    output_path, error = convert_document(filepath, output_format)
    if error:
        return jsonify({'error': error}), 500

    return jsonify({
        'converted': output_path,
        'format': output_format
    })

@app.route('/api/documents/analyze', methods=['POST'])
def analyze():
    """Run custom analysis script on document."""
    data = request.get_json()
    if not data or 'filename' not in data:
        return jsonify({'error': 'filename required'}), 400

    filename = sanitize_filename(data['filename'])
    filepath = os.path.join(UPLOAD_DIR, filename)

    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    # Run analysis - uses the file content
    analysis_script = data.get('script', 'default_analysis')
    cmd = f'/opt/analyzers/{analysis_script} {filepath}'
    result = subprocess.run(
        cmd, shell=True, capture_output=True, text=True, timeout=30
    )

    return jsonify({
        'stdout': result.stdout,
        'stderr': result.stderr,
        'returncode': result.returncode
    })

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
